diff --git a/src/test/fs_tests.cpp b/src/test/fs_tests.cpp
index 7fd1de00e0..950f3fc2af 100644
--- a/src/test/fs_tests.cpp
+++ b/src/test/fs_tests.cpp
@@ -12,6 +12,14 @@
 #include <ios>
 #include <string>

+#ifdef WIN32
+    #include <io.h>
+    #include <windows.h>
+#else
+    #include <fcntl.h>
